__NUXT_JSONP__("/finanzas-publicas/noticias/gasto_propuesto_para_salud_en_el_2026_continua_dejando_de_lado_a_poblacion_sin_seguridad_social_ethos", (function(a,b,c,d,e,f){return {data:[{post:{slug:"gasto_propuesto_para_salud_en_el_2026_continua_dejando_de_lado_a_poblacion_sin_seguridad_social_ethos",title:"Gasto propuesto para salud en el 2026 continúa dejando de lado a población sin seguridad social: Ethos",date:"2025-09-29T20:53:05.856Z",img:"https:\u002F\u002Fucarecdn.com\u002Fab279bb1-9018-456e-b78b-435513b38f7b\u002F","img-alt":"Gasto en salud ",autor:"Belén Saldívar, El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Feconomia\u002Fgasto-propuesto-salud-2026-continua-dejando-lado-poblacion-seguridad-social-ethos-20250928-779108.html",category:"finanzas-publicas",extracto:"Crecerá 5.9% anual, representa sólo 2.6% del PIB, muy por debajo de la recomendación de la OMS de 6%.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"El presupuesto que propone el gobierno federal para el rubro de salud, el siguiente año, continúa dejando a un lado a la población que no cuenta con "},{type:b,tag:e,props:{},children:[{type:a,value:"seguridad social"}]},{type:a,value:", de acuerdo con un análisis de la "},{type:b,tag:e,props:{},children:[{type:a,value:"organización civil Ethos Innovación"}]},{type:a,value:" en "},{type:b,tag:e,props:{},children:[{type:a,value:"Políticas Públicas"}]},{type:a,value:"."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El "},{type:b,tag:e,props:{},children:[{type:a,value:"Proyecto de Presupuesto de Egresos de la Federación (PPEF) 2026"}]},{type:a,value:" propone un gasto en salud por 996,254 millones de pesos, considerando dentro de este los recursos que se destinan a la Secretaría de Salud, el "},{type:b,tag:e,props:{},children:[{type:a,value:"IMSS-Bienestar, el FASSA"}]},{type:a,value:", el resto de la función salud, y los programas presupuestarios "},{type:b,tag:e,props:{},children:[{type:a,value:"Salud casa por casa (Bienestar)"}]},{type:a,value:", Servicios médicos al personal de Pemex e Investigación y desarrollo tecnológico en salud "},{type:b,tag:e,props:{},children:[{type:a,value:"(IMSS e ISSSTE)."}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De ser aprobado, el gasto en salud crecerá 5.9% en comparación anual; sin embargo, representa sólo 2.6% del "},{type:b,tag:e,props:{},children:[{type:a,value:"Producto Interno Bruto (PIB)"}]},{type:a,value:", muy por debajo de la recomendación de la "},{type:b,tag:e,props:{},children:[{type:a,value:"Organización Mundial de la Salud (OMS)"}]},{type:a,value:" de 6 por ciento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La organización Ethos explicó que el crecimiento en el gasto en salud se debió, principalmente, al incremento que se propone a los programas de salud del IMSS, que cuentan con 557,232 millones de pesos, 11.7% más que el aprobado en el 2025."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sin embargo, la organización subrayó que el incremento a estos programas del IMSS es beneficioso sólo para la población que cuenta con seguridad social, dado que la que no tiene acceso a ella es atendida principalmente por la Secretaría de Salud y el IMSS-Bienestar, cuyos recursos son menores."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El PPEF 2026 propone que el IMSS-Bienestar tenga un presupuesto de 172,492 millones de pesos, apenas 0.8% más en comparación con lo aprobado este año, mientras que para la Secretaría de Salud se proponen 66,826 millones de pesos, 3.2% menos anual."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"\"A pesar de que el presupuesto en salud para el 2026 crece, su diseño prioriza a quienes ya tienen seguridad social, dejando rezagados los servicios y la prevención para quienes no cuentan con cobertura y continúan siendo la población más vulnerable\", aseveró la organización."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De acuerdo con la última Medición de la Pobreza Multidimensional, en México 34 de cada 100 personas no cuenta con acceso a servicios de salud, lo que se traduce a 44.5 millones de personas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Sin recursos"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el análisis, se señala que el motivo por el cual el gasto de la Secretaría de Salud cae para el siguiente año se debe a que no se proyectaron recursos para 10 programas de la institución."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Dichos programas están relacionados a la prevención de enfermedades crónicas, el VIH, la capacitación de personal médico y la infraestructura social de salud."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“En la práctica, se fortalece la atención, pero se debilitan programas preventivos y servicios destinados a quienes carecen de seguridad social, que es justamente la población más vulnerable”, consignó Ethos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Por otro lado, señaló el aumento de 93.3% del programa de Salud Casa por Casa, lo cual consideró como un esfuerzo para robustecer esquemas de atención primaria a la población con movilidad limitada, así como a personas adultas mayores y con discapacidad."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"No obstante, indicó que la escala de este programa sigue siendo pequeña frente al peso del presupuesto general, ya que los recursos que se proponen suman apenas 4,000 millones de pesos, mientras que el gasto total asciende a 10.1 billones de pesos."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fgasto_propuesto_para_salud_en_el_2026_continua_dejando_de_lado_a_poblacion_sin_seguridad_social_ethos",extension:".md",createdAt:f,updatedAt:f}}],fetch:{},mutations:[]}}("text","element","p","\n","strong","2025-11-25T01:24:03.268Z")));